function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*99991+53);var agents=['scout','planner','builder','checker','reporter'];var skills={};agents.forEach(function(a){skills[a]=['search','plan','build','verify','report'].filter(function(){return R()<0.5;});});var tasks=['research','design','implement','test'];var plan=tasks.map(function(t){var who=agents.filter(function(a){return skills[a].length>0;});return{task:t,assigned:who.length?who[(R()*who.length)|0]:'none'};});var rounds=3;var covered=plan.filter(function(p){return p.assigned!=='none';}).length;return{agents:agents,plan:plan,simulated_rounds:rounds,messages_exchanged:rounds*plan.length,task_coverage_pct:+(covered/tasks.length*100).toFixed(0)};}
var SEED = 92001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

